// src/commands/init.js import path from 'path'; import fs from 'fs-extra'; import chalk from 'chalk'; import ora from 'ora'; import inquirer from 'inquirer'; import { execa } from 'execa'; export async function init(options) { console.log(chalk.blue('
🚀 Create a new project
')); // 1. 收集信息 const answers = await inquirer.prompt([ { type: 'input', name: 'name', message: 'Project name:', default: 'my-project', validate: (input) => { if (!/^[a-z0-9-]+$/.test(input)) { return 'Name can only contain lowercase letters, numbers, and hyphens'; } return true; }, }, { type: 'list', name: 'template', message: 'Select a template:', choices: ['react', 'vue', 'vanilla'], default: options.template, }, { type: 'checkbox', name: 'features', message: 'Select features:', choices: [ { name: 'TypeScript', value: 'typescript', checked: true }, { name: 'ESLint', value: 'eslint' }, { name: 'Prettier', value: 'prettier' }, ], }, ]); const projectDir = path.resolve(process.cwd(), answers.name); // 2. 检查目录 if (await fs.pathExists(projectDir)) { const { overwrite } = await inquirer.prompt([ { type: 'confirm', name: 'overwrite', message: `Directory ${answers.name} already exists. Overwrite?`, default: false, }, ]); if (!overwrite) { console.log(chalk.yellow('Cancelled')); return; } await fs.remove(projectDir); } // 3. 创建项目 const spinner = ora('Creating project...').start(); try { await fs.ensureDir(projectDir); // 复制模板 const templateDir = path.join(__dirname, '..', 'templates', answers.template); await fs.copy(templateDir, projectDir); // 更新 package.json const pkgPath = path.join(projectDir, 'package.json'); const pkg = await fs.readJson(pkgPath); pkg.name = answers.name; await fs.writeJson(pkgPath, pkg, { spaces: 2 }); spinner.succeed('Project created'); // 4. 安装依赖 spinner.start('Installing dependencies...'); await execa('npm', ['install'], { cwd: projectDir }); spinner.succeed('Dependencies installed'); // 5. 完成 console.log(chalk.green('
✨ Done! Now run:
')); console.log(chalk.cyan(` cd ${answers.name}`)); console.log(chalk.cyan(' npm run dev
')); } catch (error) { spinner.fail('Failed to create project'); console.error(chalk.red(error.message)); process.exit(1); } }
